  ];

  var grid = document.getElementById('projectsGrid');
  if (grid) {
    for (var i = 0; i < projects.length; i++) {
      (function(project, index) {
        var item = document.createElement('div');
        item.className = 'project-full-item';
        item.innerHTML = 
          '<div class="proj-gradient"></div>' +
          '<img src="' + project.image + '" alt="' + project.title + '" loading="lazy"/>' +
          '<div class="project-full-info">' +
            '<span class="proj-category-tag" style="background:' + project.theme + ';">' + project.category + '</span>' +
            '<h2 class="font-serif">' + project.title + '</h2>' +
            '<p class="proj-short-desc">' + project.desc + '</p>' +
            '<button class="proj-link-btn" onclick="event.stopPropagation();openQuickModal(projects[' + index + ']);">View Details <span>→</span></button>' +
          '</div>';
        item.onclick = function() { openQuickModal(project); };
        grid.appendChild(item);
      })(projects[i], i);
    }

    function revealItems() {
      var items = document.querySelectorAll('.project-full-item');
      for (var c = 0; c < items.length; c++) {
        if (items[c].getBoundingClientRect().top < window.innerHeight - 80) {
          items[c].classList.add('visible');
        }
      }
    }
    window.addEventListener('scroll', revealItems);
    window.addEventListener('load', revealItems);
    revealItems();
  }

  function openQuickModal(project) {
    var modal = document.getElementById('quickModal'), content = document.getElementById('quickModalContent');
    content.innerHTML = 
      '<button class="modal-close" onclick="closeQuickModal()" type="button">✕</button>' +
      '<img src="' + project.image + '" alt="' + project.title + '" style="width:100%;height:400px;object-fit:cover;"/>' +
      '<div style="padding:30px;">' +
        '<span style="display:inline-block;background:' + project.theme + ';color:#fff;padding:6px 16px;border-radius:20px;font-size:11px;font-weight:700;letter-spacing:1px;margin-bottom:12px;">' + project.category + '</span>' +
        '<h2 class="font-serif" style="font-size:28px;margin:0 0 15px 0;color:#1c1917;">' + project.title + '</h2>' +
        '<p style="color:#666;line-height:1.8;margin-bottom:20px;">' + project.fullDesc + '</p>' +
        '<button onclick="closeQuickModal();openFullModal(\'' + project.title.replace(/'/g, "\\'") + '\');" style="display:inline-flex;align-items:center;gap:8px;background:#c9a96e;color:#fff;padding:14px 30px;border-radius:12px;font-weight:600;font-size:14px;border:none;cursor:pointer;">View Full Gallery →</button>' +
      '</div>';
    modal.style.display = 'flex'; document.body.style.overflow = 'hidden';
  }
  function closeQuickModal() { document.getElementById('quickModal').style.display = 'none'; document.body.style.overflow = ''; }

  function openFullModal(title) {
    var project = null;
    for (var i = 0; i < projects.length; i++) { if (projects[i].title === title) { project = projects[i]; break; } }
    if (!project) return;
    var modal = document.getElementById('fullModal'), content = document.getElementById('fullModalContent');
    var galleryHtml = '';
    for (var j = 0; j < project.gallery.length; j++) { 
      galleryHtml += '<img src="' + project.gallery[j] + '" alt="Gallery" loading="lazy" style="cursor:pointer;" onclick="event.stopPropagation();openImageViewer(\'' + project.gallery[j] + '\');"/>'; 
    }
    var detailsHtml = '';
    for (var d = 0; d < project.details.length; d++) { 
      detailsHtml += '<li style="background:#f5f5f5;padding:8px 16px;border-radius:20px;font-size:13px;color:#555;display:inline-block;margin:4px;">' + project.details[d] + '</li>'; 
    }
    content.innerHTML = 
      '<button class="modal-close" onclick="closeFullModal()" type="button">✕</button>' +
      '<div style="padding:30px;">' +
        '<span style="display:inline-block;background:' + project.theme + ';color:#fff;padding:6px 16px;border-radius:20px;font-size:11px;font-weight:700;letter-spacing:1px;margin-bottom:12px;">' + project.category + '</span>' +
        '<h2 class="font-serif" style="font-size:32px;margin:0 0 20px 0;color:#1c1917;">' + project.title + '</h2>' +
        '<p style="color:#666;line-height:2;font-size:16px;margin-bottom:20px;">' + project.fullDesc + '</p>' +
        '<ul style="list-style:none;padding:0;margin-bottom:20px;">' + detailsHtml + '</ul>' +
      '</div>' +
      '<div class="full-modal-gallery">' + galleryHtml + '</div>' +
      '<div style="padding:20px 30px 30px;text-align:center;">' +
        '<button onclick="closeFullModal();openConsultation();" style="display:inline-flex;align-items:center;gap:8px;background:#c9a96e;color:#fff;padding:16px 40px;border-radius:12px;font-weight:600;font-size:16px;border:none;cursor:pointer;">Get a Quote</button>' +
      '</div>';
    modal.style.display = 'flex'; document.body.style.overflow = 'hidden';
  }
  function closeFullModal() { document.getElementById('fullModal').style.display = 'none'; document.body.style.overflow = ''; }
  function openConsultation() { document.getElementById('consultationModal').style.display = 'flex'; }
  function closeConsultation() { document.getElementById('consultationModal').style.display = 'none'; }

  // ============ Image Viewer ============
  var imageViewer = document.createElement('div');
  imageViewer.className = 'image-viewer';
  imageViewer.innerHTML = '<button class="image-viewer-close" onclick="closeImageViewer()">✕</button><img src="" alt="Zoomed" id="zoomedImg"/>';
  imageViewer.onclick = function(e) { if (e.target === imageViewer || e.target.classList.contains('image-viewer-close')) closeImageViewer(); };
  document.body.appendChild(imageViewer);

  function openImageViewer(src) {
    document.getElementById('zoomedImg').src = src;
    imageViewer.classList.add('active');
    document.body.style.overflow = 'hidden';
  }
  function closeImageViewer() {
    imageViewer.classList.remove('active');
    document.body.style.overflow = '';
  }

  document.addEventListener('keydown', function(e) { 
    if (e.key === 'Escape') { closeQuickModal(); closeFullModal(); closeConsultation(); closeImageViewer(); } 
  });

  lucide.createIcons();

// ============ زر الصعود للأعلى ============
var backToTopBtn = document.createElement('button');
backToTopBtn.className = 'back-to-top';
backToTopBtn.innerHTML = '↑';
backToTopBtn.setAttribute('aria-label', 'Back to top');
backToTopBtn.onclick = function() {
  window.scrollTo({ top: 0, behavior: 'smooth' });
};
document.body.appendChild(backToTopBtn);

window.addEventListener('scroll', function() {
  var scrollHeight = document.documentElement.scrollHeight;
  var clientHeight = window.innerHeight;
  if (window.scrollY + clientHeight >= scrollHeight - 200) {
    backToTopBtn.classList.add('show');
  } else {
    backToTopBtn.classList.remove('show');
  }
});
// ============ Preloader ============
window.addEventListener('load', function() {
  var loader = document.getElementById('pageLoader');
  setTimeout(function() {
    loader.classList.add('hidden');
    setTimeout(function() {
      loader.remove();
    }, 600);
  }, 2000);
});
