(function() {
  var ts=document.createElement('style');ts.textContent='.mk-toast{position:fixed;bottom:30px;left:50%;transform:translateX(-50%) translateY(100px);background:#1a1a1a;color:#fff;padding:14px 28px;border-radius:50px;font-family:Inter,sans-serif;font-size:14px;font-weight:500;z-index:999999;opacity:0;transition:all 0.4s;box-shadow:0 10px 40px rgba(0,0,0,0.4);display:flex;align-items:center;gap:10px;border:1px solid rgba(255,255,255,0.1);direction:rtl;white-space:nowrap}.mk-toast.show{opacity:1;transform:translateX(-50%) translateY(0)}.mk-toast-icon{font-size:18px;animation:mk-shake 0.5s ease}@keyframes mk-shake{0%,100%{transform:rotate(0)}25%{transform:rotate(-10deg)}75%{transform:rotate(10deg)}}.mk-toast.warning{background:#d97706}.mk-toast.error{background:#dc2626}';document.head.appendChild(ts);
  var tc=document.createElement('div');tc.id='mkToastContainer';document.body.appendChild(tc);
  function st(m,t){t=t||'warning';var i={warning:'⚠️',error:'🚫'};var to=document.createElement('div');to.className='mk-toast '+t;to.innerHTML='<span class="mk-toast-icon">'+(i[t]||'⚠️')+'</span><span>'+m+'</span>';tc.appendChild(to);setTimeout(function(){to.classList.add('show')},10);setTimeout(function(){to.classList.remove('show');setTimeout(function(){to.remove()},400)},2500)}
  document.addEventListener('copy',function(e){e.preventDefault();st('Copy not allowed','error');return false});
  document.addEventListener('cut',function(e){e.preventDefault();st('Cut not allowed','error');return false});
  document.addEventListener('contextmenu',function(e){e.preventDefault();st('Right click disabled','warning');return false});
  document.addEventListener('keydown',function(e){if((e.ctrlKey||e.metaKey)&&e.key==='c'){e.preventDefault();st('Copy disabled','error');return false}if((e.ctrlKey||e.metaKey)&&e.key==='x'){e.preventDefault();st('Cut disabled','error');return false}if(e.key==='F12'){e.preventDefault();return false}});
  document.addEventListener('dragstart',function(e){e.preventDefault();return false});
  document.addEventListener('selectstart',function(e){e.preventDefault();return false});
})();
